//! More differential checks against the Python engine (fixture generated by
//! `tests/fixtures/gen_llm_parity2.py`): URL rules and `.local` resolution, batching, checkpoint file names,
//! profile reprs / generation options / chat messages, inline-markup and reply-parser fuzz.

use std::io;
use std::net::Ipv4Addr;

use serial_test::serial;

use se_core::{Sentence, Value, json};
use se_translate::external::{
    api_key_transport_allowed, external_models_url, is_local_network_host, is_opencode_go_url,
    normalize_external_chat_url,
};
use se_translate::lan::{LanNet, resolve_lan_url_with};
use se_translate::llm::translation_batches;
use se_translate::profiles::profile_for_model;
use se_translate::prompts::parse_numbered_translations;
use se_translate::validate::has_inline_markup;

fn fixture() -> Value {
    let text =
        std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/llm_parity2.json")).unwrap();
    json::parse(&text).unwrap()
}

fn arr<'a>(v: &'a Value, k: &str) -> &'a [Value] {
    v.get(k).and_then(Value::as_array).unwrap()
}

fn s<'a>(v: &'a Value, k: &str) -> &'a str {
    v.get(k).and_then(Value::as_str).unwrap()
}

fn opt<'a>(v: &'a Value, k: &str) -> Option<&'a str> {
    v.get(k).and_then(Value::as_str)
}

struct FixedNet {
    ip: Option<Ipv4Addr>,
    scan: Option<&'static str>,
}

impl LanNet for FixedNet {
    fn getaddrinfo_v4(&self, _host: &str, _port: u16) -> io::Result<Vec<Ipv4Addr>> {
        self.ip.map(|ip| vec![ip]).ok_or_else(|| io::Error::other("x"))
    }

    fn discover_lan_server_ip(&self, _port: u16) -> Option<String> {
        self.scan.map(str::to_string)
    }
}

#[test]
#[serial]
fn test_url_rules_and_lan_resolution_match_python() {
    unsafe { std::env::remove_var(se_core::i18n::ENV_VAR) };
    se_core::i18n::set_language(None);
    let f = fixture();
    let rows = arr(&f, "urls");
    assert!(rows.len() > 1000);
    let mut wrong = Vec::new();
    for c in rows {
        let url = s(c, "url");
        let mut check = |what: &str, ok: bool| {
            if !ok {
                wrong.push(format!("{what}: {url:?}"));
            }
        };
        check("host", se_translate::pyurl::url_host(url).as_deref() == opt(c, "host"));
        check("allowed", api_key_transport_allowed(url) == c.get("allowed").unwrap().as_bool().unwrap());
        if let Some(b) = c.get("opencode").and_then(Value::as_bool) {
            check("opencode", is_opencode_go_url(url) == b);
        }
        match normalize_external_chat_url(url) {
            Ok(v) => {
                check("normalize", Some(v.as_str()) == opt(c, "ok"));
                if opt(c, "ok").is_none() {
                    continue;
                }
                check("norm_models", external_models_url(&v).as_deref() == opt(c, "norm_models"));
                let host = se_translate::pyurl::url_host(&v);
                check("norm_host", host.as_deref() == opt(c, "norm_host"));
                check("norm_local", is_local_network_host(host.as_deref()) == c.get("norm_local").unwrap().as_bool().unwrap());
                let resolved = resolve_lan_url_with(&v, false, &FixedNet { ip: Some(Ipv4Addr::new(10, 1, 2, 3)), scan: None });
                check("resolved", Some(resolved.as_str()) == opt(c, "resolved"));
                let failing = FixedNet { ip: None, scan: Some("192.168.7.7") };
                check("scanned", Some(resolve_lan_url_with(&v, true, &failing).as_str()) == opt(c, "scanned"));
                check("unscanned", Some(resolve_lan_url_with(&v, false, &failing).as_str()) == opt(c, "unscanned"));
            }
            Err(e) => check("normalize err", Some(e.to_string().as_str()) == opt(c, "err")),
        }
    }
    assert!(wrong.is_empty(), "{} mismatches: {:#?}", wrong.len(), &wrong[..wrong.len().min(40)]);
}

#[test]
fn test_translation_batches_match_python() {
    let f = fixture();
    for c in arr(&f, "batches") {
        let sentences: Vec<Sentence> = arr(c, "sentences").iter().map(|v| Sentence::from_value(v).unwrap()).collect();
        let refs: Vec<&Sentence> = sentences.iter().collect();
        let limit = c.get("limit").and_then(Value::as_i64).unwrap() as usize;
        let expected: Vec<(usize, usize)> = arr(c, "ranges")
            .iter()
            .map(|r| {
                let r = r.as_array().unwrap();
                (r[0].as_i64().unwrap() as usize, r[1].as_i64().unwrap() as usize)
            })
            .collect();
        assert_eq!(translation_batches(&refs, limit), expected, "limit {limit}");
    }
}

#[test]
#[serial]
fn test_checkpoint_names_match_python() {
    unsafe {
        std::env::remove_var(se_translate::external::EXTERNAL_LLM_URL_ENV_VAR);
        std::env::remove_var(se_translate::external::EXTERNAL_LLM_MODEL_ENV_VAR);
    }
    let f = fixture();
    for c in arr(&f, "checkpoints") {
        let sentences: Vec<Sentence> = arr(c, "sentences").iter().map(|v| Sentence::from_value(v).unwrap()).collect();
        let name = se_translate::checkpoint::checkpoint_file_name(
            s(c, "model"),
            s(c, "target"),
            opt(c, "source"),
            &sentences,
            s(c, "prompt"),
        );
        assert_eq!(name, s(c, "name"), "{c:?}");
    }
}

#[test]
fn test_profiles_match_python() {
    let f = fixture();
    for c in arr(&f, "profiles") {
        let p = profile_for_model(s(c, "model"));
        assert_eq!(p.py_repr(), s(c, "repr"));
        assert_eq!(json::dumps(&p.generation_options(false), true), s(c, "openai"));
        assert_eq!(json::dumps(&p.generation_options(true), true), s(c, "ollama"));
        let messages: Vec<Value> = p
            .chat_messages("S", "U")
            .into_iter()
            .map(|m| Value::Object(se_core::Map::new().with("role", m.role).with("content", m.content)))
            .collect();
        assert_eq!(json::dumps(&Value::Array(messages), false), s(c, "messages"));
    }
}

#[test]
fn test_inline_markup_and_parser_fuzz_match_python() {
    let f = fixture();
    for c in arr(&f, "markup") {
        let c = c.as_array().unwrap();
        let text = c[0].as_str().unwrap();
        assert_eq!(has_inline_markup(text), c[1].as_bool().unwrap(), "{text:?}");
    }
    for c in arr(&f, "parser") {
        let raw = s(c, "raw");
        let n = c.get("n").and_then(Value::as_i64).unwrap() as usize;
        let mut expected: Vec<(usize, String)> = c
            .get("out")
            .and_then(Value::as_object)
            .unwrap()
            .iter()
            .map(|(k, v)| (k.parse().unwrap(), v.as_str().unwrap().to_string()))
            .collect();
        expected.sort();
        let got: Vec<(usize, String)> = parse_numbered_translations(raw, n).into_iter().collect();
        assert_eq!(got, expected, "{raw:?} n={n}");
    }
}
